# infrastructure/repositories.py
@dataclass(frozen=True)
class Order:
    id: OrderId
    total: Money        # value object spread over two columns

def order_entity_from_model(row: OrderModel) -> Order:
    return Order(OrderId(row.id), Money(row.total_amount, row.total_currency))

class OrderRepository:
    def get(self, id: OrderId) -> Order:
        return order_entity_from_model(self.session.get(OrderModel, id.value))
